## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;

  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;
  localparam int BIT_CLKS = int'(PRESCALE) * 8;

  localparam int GLITCH_DELAY = 8;
  localparam int GLITCH_WIDTH = 1;

  logic clk = 1'b0;
  logic rst = 1'b1;

  logic rxd = 1'b1;
  logic [15:0] prescale = PRESCALE;

  logic [7:0] s_axis_tdata = 8'h00;
  logic s_axis_tvalid = 1'b0;
  logic m_axis_tready = 1'b1;

  wire [7:0] m_axis_tdata;
  wire m_axis_tvalid;
  wire s_axis_tready;
  wire txd;
  wire tx_busy;
  wire rx_busy;
  wire rx_overrun_error;
  wire rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),

    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),

    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),

    .rxd(rxd),
    .txd(txd),

    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),

    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic send_byte_glitch(input logic [7:0] b, input int glitch_bit);
    rxd = 1'b0;
    wait_clks(BIT_CLKS);

    for (int i = 0; i < 8; i++) begin
      if (i == glitch_bit) begin
        rxd = b[i];
        wait_clks(GLITCH_DELAY);

        rxd = (b[i] == 1'b0) ? 1'b1 : 1'b0;
        wait_clks(GLITCH_WIDTH);

        rxd = b[i];
        wait_clks(BIT_CLKS - GLITCH_DELAY - GLITCH_WIDTH);
      end else begin
        rxd = b[i];
        wait_clks(BIT_CLKS);
      end
    end

    rxd = 1'b1;
    wait_clks(BIT_CLKS);
  endtask

  initial begin
    wait_clks(4);
    rst = 1'b0;
    wait_clks(2);

    // First frame: 8'hA5 with a glitch in bit 4.
    // A5 = 1010 0101b, bits 3 and 4 are both 0, so no normal transition
    // occurs in that sample interval except the injected glitch.
    send_byte_glitch(8'hA5, 4);

    wait_clks(16);

    // Second frame: 8'h5A with a glitch in bit 2.
    // 5A = 0101 1010b, bits 1 and 2 are both 1, so the glitch is the only
    // transition in that sample interval.
    send_byte_glitch(8'h5A, 2);

    wait_clks(20);
    $finish;
  end

  initial begin
    #100000;
    $finish;
  end

endmodule
